// --- W3C trace context propagation (middleware sketch) ---
function parseTraceparent(header) {
  // format: 00-<traceId32>-<parentSpanId16>-<flags2>
  if (!header) return null
  const parts = header.split("-")
  if (parts.length !== 4 || parts[0] !== "00") return null
  return { traceId: parts[1], parentId: parts[2] }
}

function makeSpan(ctx, name, durationMs, attrs = {}) {
  return {
    traceId: ctx.traceId,
    spanId: Math.random().toString(16).slice(2, 10),
    parentSpanId: ctx.parentId,
    name,
    durationMs,
    ...attrs
  }
}

// --- health endpoints: two questions, two endpoints ---
// GET /live  -> process alive? NEVER check dependencies here.
// GET /ready -> can this instance serve? dependencies OK.
function readiness({ db, migrations }) {
  return db.connected && migrations.applied // else: 503, LB sheds traffic
}

